CREATE DATABASE IF NOT EXISTS creditlens CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE creditlens;
CREATE TABLE IF NOT EXISTS users(user_id INT AUTO_INCREMENT PRIMARY KEY,full_name VARCHAR(100) NOT NULL,email VARCHAR(120) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('Admin','Loan Officer') DEFAULT 'Admin',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS Customers(customer_id INT AUTO_INCREMENT PRIMARY KEY,full_name VARCHAR(100) NOT NULL,email VARCHAR(100) UNIQUE,phone VARCHAR(15),address VARCHAR(255),monthly_income DECIMAL(12,2) DEFAULT 0,employment_type VARCHAR(50),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS LoanApplications(application_id INT AUTO_INCREMENT PRIMARY KEY,customer_id INT NOT NULL,loan_amount DECIMAL(12,2) NOT NULL,loan_purpose VARCHAR(100),tenure_months INT NOT NULL,application_date DATE DEFAULT (CURRENT_DATE),status ENUM('Pending','Approved','Rejected') DEFAULT 'Pending',FOREIGN KEY(customer_id) REFERENCES Customers(customer_id));
CREATE TABLE IF NOT EXISTS Loans(loan_id INT AUTO_INCREMENT PRIMARY KEY,application_id INT NOT NULL UNIQUE,principal DECIMAL(12,2) NOT NULL,interest_rate DECIMAL(5,2) NOT NULL DEFAULT 10,tenure_months INT NOT NULL,start_date DATE,status ENUM('Active','Closed','Defaulted') DEFAULT 'Active',FOREIGN KEY(application_id) REFERENCES LoanApplications(application_id));
CREATE TABLE IF NOT EXISTS Payments(payment_id INT AUTO_INCREMENT PRIMARY KEY,loan_id INT NOT NULL,amount_paid DECIMAL(12,2) NOT NULL,payment_date DATE NOT NULL,payment_status ENUM('Paid','Late','Failed') DEFAULT 'Paid',FOREIGN KEY(loan_id) REFERENCES Loans(loan_id));
CREATE TABLE IF NOT EXISTS CreditAssessments(assessment_id INT AUTO_INCREMENT PRIMARY KEY,customer_id INT NOT NULL,credit_score INT,debt_to_income DECIMAL(5,2),risk_level ENUM('Low','Medium','High') NOT NULL,assessment_date DATE DEFAULT (CURRENT_DATE),FOREIGN KEY(customer_id) REFERENCES Customers(customer_id));
CREATE TABLE IF NOT EXISTS LoanSchedules(schedule_id INT AUTO_INCREMENT PRIMARY KEY,loan_id INT NOT NULL,due_date DATE NOT NULL,due_amount DECIMAL(12,2) NOT NULL,status ENUM('Pending','Paid','Overdue') DEFAULT 'Pending',FOREIGN KEY(loan_id) REFERENCES Loans(loan_id));
CREATE INDEX idx_app_status ON LoanApplications(status); CREATE INDEX idx_schedule_due ON LoanSchedules(status,due_date); CREATE INDEX idx_payment_loan ON Payments(loan_id,payment_date);
